// Generates lib/bundle/schemas.generated.ts (the schema index) and lib/bundle/types/*.ts
// from cadmium-spec/spec/schema and cadmium-spec/systems/*/ (AGENTS.md, Setup step 3).
// Generated files are never edited by hand; rerun `pnpm gen` instead.
import { readdirSync, readFileSync, writeFileSync, mkdirSync, rmSync } from "node:fs";
import { join, relative, dirname } from "node:path";
import { compile } from "json-schema-to-typescript";

const ROOT = join(dirname(new URL(import.meta.url).pathname), "..");
const SPEC = join(ROOT, "cadmium-spec");
const BASE = "https://schema.dungeon-crawler.invalid/v1/";
const OUT_INDEX = join(ROOT, "lib/bundle/schemas.generated.ts");
const OUT_TYPES = join(ROOT, "lib/bundle/types");
const HEADER = "// GENERATED by scripts/gen-bundle.ts from cadmium-spec. Do not edit.\n";

interface SchemaFile {
  path: string; // absolute
  rel: string; // relative to cadmium-spec
  id: string; // $id
  ident: string; // TS identifier
}

function schemaFiles(): SchemaFile[] {
  const dirs = [join(SPEC, "spec/schema")];
  for (const sys of readdirSync(join(SPEC, "systems")).sort()) dirs.push(join(SPEC, "systems", sys));
  const files: SchemaFile[] = [];
  for (const dir of dirs) {
    for (const name of readdirSync(dir).sort()) {
      if (!name.endsWith(".schema.json")) continue;
      const path = join(dir, name);
      const schema = JSON.parse(readFileSync(path, "utf8")) as { $id?: string };
      const rel = relative(SPEC, path);
      const expected = BASE + (rel.startsWith("spec/schema/") ? rel.slice("spec/schema/".length) : rel);
      if (schema.$id !== expected) throw new Error(`${rel}: $id ${schema.$id} is not ${expected}`);
      files.push({ path, rel, id: schema.$id, ident: identFor(rel) });
    }
  }
  return files;
}

function identFor(rel: string): string {
  const stem = rel
    .replace(/^spec\/schema\//, "")
    .replace(/\.schema\.json$/, "")
    .replace(/^systems\//, "");
  return stem
    .split(/[/_-]/)
    .map((p, i) => (i === 0 ? p : p[0]!.toUpperCase() + p.slice(1)))
    .join("") + "Schema";
}

function dataFiles(): { rel: string; ident: string }[] {
  const out: { rel: string; ident: string }[] = [];
  for (const sys of readdirSync(join(SPEC, "systems")).sort()) {
    for (const name of ["data.json", "modules.json"]) {
      try {
        readFileSync(join(SPEC, "systems", sys, name));
      } catch {
        continue;
      }
      out.push({ rel: `systems/${sys}/${name}`, ident: sys + (name === "data.json" ? "Data" : "Modules") });
    }
  }
  return out;
}

async function main(): Promise<void> {
  const files = schemaFiles();
  const data = dataFiles();
  const importPath = (rel: string): string =>
    relative(dirname(OUT_INDEX), join(SPEC, rel)).replace(/^(?!\.)/, "./");

  let index = HEADER;
  for (const f of files) index += `import ${f.ident} from "${importPath(f.rel)}";\n`;
  for (const d of data) index += `import ${d.ident} from "${importPath(d.rel)}";\n`;
  index += `\nexport const SCHEMA_BASE = ${JSON.stringify(BASE)};\n\n`;
  index += "/** Every schema of the specification, keyed by `$id`. */\n";
  index += "export const SCHEMAS: Readonly<Record<string, object>> = {\n";
  for (const f of files) index += `  ${JSON.stringify(f.id)}: ${f.ident},\n`;
  index += "};\n\n";
  index += "/** Rules data per system id: `data.json` and, when present, `modules.json`. */\n";
  index += "export const SYSTEM_DATA: Readonly<Record<string, { data: unknown; modules?: unknown }>> = {\n";
  const systems = [...new Set(data.map((d) => d.rel.split("/")[1]!))];
  for (const sys of systems) {
    const mod = data.find((d) => d.rel === `systems/${sys}/modules.json`);
    index += `  ${sys}: { data: ${sys}Data${mod ? `, modules: ${mod.ident}` : ""} },\n`;
  }
  index += "};\n";
  writeFileSync(OUT_INDEX, index);

  rmSync(OUT_TYPES, { recursive: true, force: true });
  mkdirSync(OUT_TYPES, { recursive: true });
  const byId = new Map(files.map((f) => [f.id, f]));
  const exports: string[] = [];
  for (const f of files) {
    const schema = selfContained(f, byId);
    const ts = await compile(schema, f.ident.replace(/Schema$/, ""), {
      bannerComment: HEADER.trim(),
      additionalProperties: false,
      strictIndexSignatures: true,
      unreachableDefinitions: f.rel === "spec/schema/defs.schema.json",
      format: true,
    });
    const out = f.ident.replace(/Schema$/, "");
    writeFileSync(join(OUT_TYPES, `${out}.ts`), ts);
    exports.push(`export * as ${out} from "./${out}";`);
  }
  writeFileSync(join(OUT_TYPES, "index.ts"), HEADER + exports.join("\n") + "\n");
  console.log(`gen-bundle: ${files.length} schemas, ${data.length} data files`);
}

type Json = null | boolean | number | string | Json[] | { [k: string]: Json };

/**
 * Makes `f` self-contained for the code generator: every schema it references, transitively,
 * is embedded at `$defs.<Ident>`, that schema's own `$defs` are hoisted to `$defs.<Ident>__<name>`,
 * and cross-file `$ref`s are rewritten to these local pointers. Used for code generation only.
 */
function selfContained(f: SchemaFile, byId: Map<string, SchemaFile>): object {
  const load = (file: SchemaFile): { [k: string]: Json } =>
    JSON.parse(readFileSync(file.path, "utf8")) as { [k: string]: Json };
  const pending: SchemaFile[] = [];
  const embedded = new Set<string>([f.id]);
  const local = (file: SchemaFile, pointer: string): string => {
    if (file === f) return "#" + pointer;
    if (!embedded.has(file.id)) {
      embedded.add(file.id);
      pending.push(file);
    }
    const m = /^\/\$defs\/([^/]+)(.*)$/.exec(pointer);
    return m ? `#/$defs/${file.ident}__${m[1]}${m[2]}` : `#/$defs/${file.ident}${pointer}`;
  };
  const rewrite = (node: Json, owner: SchemaFile): Json => {
    if (Array.isArray(node)) return node.map((n) => rewrite(n, owner));
    if (node === null || typeof node !== "object") return node;
    const out: { [k: string]: Json } = {};
    for (const [k, v] of Object.entries(node)) {
      if (k === "$ref" && typeof v === "string") {
        const [target, pointer = ""] = v.split("#");
        const file = target === "" ? owner : byId.get(new URL(target!, owner.id).href);
        if (!file) throw new Error(`${owner.rel}: unresolved $ref ${v}`);
        out[k] = local(file, pointer);
      } else if (k === "prefixItems") {
        // The code generator reads tuples in the draft-07 form; validation uses the original.
        out.items = rewrite(v, owner);
      } else out[k] = rewrite(v, owner);
    }
    return out;
  };
  const root = rewrite(load(f), f) as { [k: string]: Json };
  const defs = ((root.$defs as { [k: string]: Json } | undefined) ??= {});
  while (pending.length > 0) {
    const file = pending.shift()!;
    const { $id: _id, $schema: _s, $defs: inner, ...rest } = load(file);
    defs[file.ident] = rewrite(rest, file);
    for (const [name, def] of Object.entries((inner ?? {}) as { [k: string]: Json })) {
      defs[`${file.ident}__${name}`] = rewrite(def, file);
    }
  }
  return root;
}

main().catch((err: unknown) => {
  console.error(err);
  process.exit(1);
});
